package com.example.historyquizru.data

import androidx.room.RoomDatabase
import androidx.sqlite.db.SupportSQLiteDatabase

object DatabaseSeeder {
    val callback = object : RoomDatabase.Callback() {
        override fun onCreate(db: SupportSQLiteDatabase) {
            super.onCreate(db)
            seed(db)
        }
    }

    private data class SeedPersonality(
        val epochId: Int,
        val name: String,
        val years: String,
        val imageName: String,
        val hint: String,
        val description: String
    )

    private fun seed(db: SupportSQLiteDatabase) {
        val epochs = listOf(
            listOf(1, "Древняя Русь", "Русь от образования первых княжеств до объединения земель", 1),
            listOf(2, "Московское царство", "Московское государство и царская власть", 2),
            listOf(3, "Российская империя", "Россия от реформ Петра I до начала XX века", 3),
            listOf(4, "СССР", "История Советского Союза", 4),
            listOf(5, "Современная Россия", "Россия с конца XX века по настоящее время", 5)
        )

        epochs.forEach { epoch ->
            db.execSQL(
                "INSERT OR IGNORE INTO epochs (id, name, description, orderIndex) VALUES (?, ?, ?, ?)",
                arrayOf(epoch[0], epoch[1], epoch[2], epoch[3])
            )
        }

        val personalities = listOf(
            SeedPersonality(1, "Рюрик", "IX век", "ryurik.jpg", "Согласно летописи, призван на княжение в 862 году. Считается основателем династии Рюриковичей.", "Летописный основатель династии Рюриковичей. Единственным источником сведений о нём является «Повесть временных лет» и восходящая к ней летописная традиция. Согласно этому тексту, в 862 году был призван на княжение племенами словен, чуди, кривичей и веси вместе с братьями Синеусом и Трувором. Братья сели в Ладоге, Белоозере и Изборске; после их смерти Рюрик принял всю власть и, по одной из летописных версий, основал Новгород. Умер в 879 году, оставив малолетнего сына Игоря на попечение родича Олега. Историчность Рюрика и достоверность летописного сказания остаются предметом научной дискуссии; вопрос о его этническом происхождении также не решён. Сама дата 862 года была официально закреплена как «начальное событие российской государственности» указом императора Николая I в 1852 году, и с тех пор призвание варягов традиционно считается точкой отсчёта русской истории. Споры о том, кем были варяги — скандинавами, славянами или балтами — и имело ли место призвание в реальности, продолжаются в историографии уже более двух столетий."),
            SeedPersonality(1, "Олег Вещий", "ум. 912", "oleg_veshiy.jpg", "В 882 году объединил Новгород и Киев. Совершил поход на Константинополь и заключил договор с Византией в 911 году.", "Князь, правивший после Рюрика. Согласно «Повести временных лет», после смерти Рюрика в 879 году принял власть как опекун малолетнего Игоря. В 882 году захватил Киев, убив Аскольда и Дира, и перенёс туда столицу, объединив северные и южные земли. Подчинил древлян, северян и радимичей, освободив их от дани Хазарскому каганату. В 907 году совершил поход на Константинополь; по летописи, войско двигалось на ладьях, поставленных на колёса, а в знак победы Олег прибил свой щит на вратах города. Под 911 годом в летописи помещён договор с Византией, обеспечивавший русским купцам право беспошлинной торговли. Обстоятельства его смерти изложены в летописном предании о коне и змее, которое легло в основу известного стихотворения Пушкина. Прозвище «Вещий» (то есть знающий будущее, провидящий) закрепилось за ним в летописной традиции. Византийские источники, подробно описывающие аналогичные походы других народов, не упоминают поход 907 года, что даёт основание части историков считать его легендарным."),
            SeedPersonality(1, "Ольга", "ок. 920–969", "olga.jpg", "Правила Русью при малолетнем Святославе. Упорядочила сбор дани и приняла христианство в Константинополе.", "Княгиня, правившая после гибели мужа, князя Игоря, при малолетнем сыне Святославе. Согласно летописи, отомстила древлянам за смерть Игоря, уничтожив их столицу Искоростень, и провела упорядочение сбора дани, установив «уроки» (фиксированные размеры повинностей) и «погосты» (места сбора дани). В историографии эти меры получили название «реформ княгини Ольги», хотя их суть не вполне выяснена: распространённое представление об упразднении полюдья и организации сети погостов как пунктов своза дани оспаривается, поскольку этимология самого термина «погост» указывает на его происхождение из практики полюдья. Около 957 года (по византийским источникам; в «Повести временных лет» называется 955 год) совершила поездку в Константинополь, где приняла христианство под именем Елены. Состав русской делегации показывает, что Ольга имела в виду не только церковные вопросы, но и обновление торгово-политического договора 944 года. Впоследствии была причислена к лику святых; официальная канонизация как равноапостольной состоялась в 1595 году."),
            SeedPersonality(1, "Святослав Игоревич", "ок. 942–972", "svyatoslav.jpg", "Князь-воин, почти всё правление проведший в походах. Разгромил Хазарский каганат, воевал с Византией, погиб в бою с печенегами.", "Киевский князь, большую часть правления проведший в военных походах; внутренними делами государства при нём в значительной мере занималась мать, княгиня Ольга. Формально стал великим князем в трёхлетнем возрасте после гибели отца в 945 году, но самостоятельное правление началось около 964 года. В 964–966 годах подчинил вятичей, ранее плативших дань хазарам, и разгромил Хазарский каганат, разрушив Саркел на Дону и Итиль на Волге; на берегах Керченского пролива основал форпост русского влияния — будущую Тмутаракань. В 967 или 968 году вторгся в Дунайскую Болгарию и обосновался на Дунае, назвав город Малая Преслава Переяславцем и объявив его своей столицей. В ходе войны с Византией в 971 году после осады Доростола заключил мир с императором Иоанном Цимисхием. Погиб в 972 году у днепровских порогов в бою с печенегами, возвращаясь на Русь. Летопись характеризует его как неприхотливого в быту воина, который не возил с собой обозов и котлов, а мясо жарил на углях, и передаёт его знаменитую фразу-предупреждение: «Иду на вы»."),
            SeedPersonality(1, "Владимир Святославич", "ок. 960–1015", "vladimir_svyatoslavich.jpg", "Крестил Русь около 988 года. Принял христианство из Византии и женился на царевне Анне.", "Киевский князь, при котором произошло Крещение Руси. Сын Святослава и Малуши, княжил сначала в Новгороде, в 978 году захватил Киев, победив брата Ярополка. Около 988 года принял христианство из Византии и женился на царевне Анне. По летописи, крестился в Корсуне (Херсонесе) и был наречён Василием, а затем крестил киевлян и начал христианизацию Руси. Вернувшись в Киев, он привёз греческих священников и способствовал обращению в веру своих сыновей, бояр и местного населения, а позже и жителей других городов. Важнейшим следствием стало учреждение Русской митрополии Константинопольского патриархата и нескольких епархий; по приказу Владимира взамен уничтожавшихся языческих идолов развернулось строительство православных храмов. Вместе с христианством из Византии на Русь пришла грамотность, центрами распространения которой стали храмы и монастыри, где образовывались школы. Впоследствии был причислен к лику святых; в народной традиции получил прозвище «Красное Солнышко»."),
            SeedPersonality(1, "Ярослав Мудрый", "ок. 978–1054", "yaroslav_mudry.jpg", "При нём составлена «Русская Правда». Строил храмы и укреплял международные связи через династические браки.", "Киевский князь, при котором был составлен первый известный письменный свод законов Руси — «Русская Правда». Сын Владимира Святославича и полоцкой княжны Рогнеды, при распределении столов получил Ростов, а после смерти старшего брата Вышеслава перешёл в Новгород. По-видимому, уже в 1010-х годах в Новгороде произошла первая кодификация обычного древнерусского права — так называемая «Правда Ярослава», древнейшая часть «Русской Правды». После смерти отца в 1015 году начал борьбу со Святополком, выступив мстителем за убийство братьев Бориса и Глеба; занял Киев после победы у Любеча в 1016 году, но окончательно утвердился на престоле лишь в 1019 году после битвы на Альте. В 1020-е годы его правление осложнялось конфликтом с братом Мстиславом Тмутараканским, завершившимся разделом государства по Днепру; лишь после смерти Мстислава в 1035 году Ярослав стал «самовластцем» на Руси. В его правление (1019–1054) были построены Софийский собор в Киеве, Золотые ворота с надвратной церковью, основаны монастыри святых Георгия и Ирины; прообразами этих сооружений были постройки Константинополя и Иерусалима. Вёл активную внешнюю политику, укреплял международные связи через династические браки: был женат на дочери шведского конунга Ингигерде, а его дочери были замужем за королями Франции, Норвегии и Венгрии. Прозвище «Мудрый» закрепилось за ним в историографии."),
            SeedPersonality(1, "Владимир Мономах", "1053–1125", "vladimir_monomakh.jpg", "Киевский князь, инициатор Любечского съезда и автор «Поучения детям».", "Владимир Всеволодович Мономах родился в 1053 году в семье князя Всеволода Ярославича и «греческой царевны», предположительно дочери византийского императора Константина IX Мономаха, от которого получил прозвище. При жизни отца княжил в Ростове, Смоленске, Чернигове, а с 1094 года — в Переяславле. После смерти отца в 1093 году уступил киевский престол двоюродному брату Святополку Изяславичу, не желая междоусобицы. Был главным инициатором Любечского съезда князей 1097 года, на котором был провозглашён принцип «каждо да держит отчину свою». В 1113 году после смерти Святополка и восстания киевлян против ростовщиков был призван на киевский престол. Издал «Устав о резах», ограничивший произвол ростовщиков, который вошёл в состав «Русской Правды». Был вдохновителем и одним из руководителей совместных походов против половцев. Умер 19 мая 1125 года. Автор «Поучения детям» — литературного памятника, соединяющего нравственные наставления с автобиографическим рассказом о походах и трудах."),
            SeedPersonality(1, "Юрий Долгорукий", "ок. 1090–1157", "yuriy_dolgorukiy.jpg", "Ростово-суздальский и киевский князь, с именем которого связано первое упоминание Москвы.", "Юрий Владимирович Долгорукий — один из младших сыновей Владимира Мономаха. Точная дата рождения дискуссионна; современные исследователи относят её к концу 1090-х — 1100 году. После смерти отца в 1125 году стал князем ростово-суздальским и перенёс столицу княжества из Ростова в Суздаль. С начала 1130-х годов боролся за южные города Переяславль и Киев, за что получил прозвище Долгорукий. При нём были основаны города Переяславль-Залесский, Юрьев-Польский, Дмитров. В 1147 году в летописи впервые упомянута Москва — в связи с приглашением Юрием своего союзника, новгород-северского князя Святослава Ольговича. В 1155 году окончательно занял Киев, но правил недолго: умер в 1157 году, по-видимому, от отравления."),
            SeedPersonality(1, "Александр Невский", "1220–1263", "nevskiy__aliexand.jpg", "Новгородский и владимирский князь, победитель шведов на Неве и Ливонского ордена на Чудском озере.", "Александр Ярославич родился 30 мая 1220 года (по старой историографической традиции; современные исследователи называют 13 мая 1221 года) в семье князя Ярослава Всеволодовича и княгини Феодосии, внук Всеволода Большое Гнездо. В 1236 году был посажен на новгородское княжение. В июле 1240 года в возрасте 19 лет разбил шведский отряд в устье реки Ижоры, за что получил прозвище Невский. 5 апреля 1242 года на льду Чудского озера разгромил войско Ливонского ордена в битве, вошедшей в историю как Ледовое побоище. В отношениях с Золотой Ордой проводил политику компромисса, несколько раз ездил в Орду и добился освобождения русских от обязанности выступать в татарских войнах. В 1262 году, возвращаясь из Орды, где пытался умиротворить хана после восстаний против данников, заболел и умер в Городце. Был похоронен во Владимире; в 1547 году причислен к лику святых."),
            SeedPersonality(1, "Дмитрий Донской", "1350–1389", "dmitry_donskoy.jpg", "Московский князь, возглавивший русские войска в Куликовской битве 1380 года.", "Дмитрий Иванович родился 12 октября 1350 года в Москве, сын князя Ивана II Красного и внук Ивана Калиты. После смерти отца в 1359 году опекуном и наставником малолетнего князя стал митрополит Алексий. В 1367 году построил в Москве первый белокаменный Кремль. В 1368 и 1370 годах московские войска отразили нападения литовского князя Ольгерда. В 1375 году принудил тверского князя Михаила Александровича к признанию своего старшинства. В 1378 году на реке Воже разбил ордынское войско Бегича, а 8 сентября 1380 года в Куликовской битве на Дону разгромил войско Мамая, за что получил прозвище Донской. В 1382 году не смог предотвратить разорения Москвы Тохтамышем и был вынужден возобновить выплату дани Орде. В духовной грамоте впервые передал великое княжение своему сыну Василию без санкции хана. Умер 19 мая 1389 года, погребён в Архангельском соборе Кремля."),
            SeedPersonality(1, "Игорь Рюрикович", "ок. 878–945", "igor_ryurikovich.jpg", "Киевский князь, сын Рюрика, погибший при сборе дани с древлян.", "Игорь Рюрикович — сын Рюрика, по летописи княжил в Киеве с 912 года после смерти Олега, правившего при его малолетстве. В 914 году подавил восстание древлян и наложил на них дань, в 915 году впервые заключил мир с печенегами, появившимися в русских степях. Совершил два похода на Византию: в 941 году русский флот был сожжён греческим огнём, а в 944 году поход завершился мирным договором, текст которого сохранился в «Повести временных лет». В 945 году по требованию дружины, недовольной своим содержанием, отправился за данью к древлянам, произвольно увеличил её размер, а затем с малой частью дружины вернулся за дополнительной данью. Древляне возмутились и убили князя. По свидетельству византийского историка Льва Диакона, Игорь был привязан к верхушкам двух нагнутых деревьев и разорван надвое."),
            SeedPersonality(1, "Андрей Боголюбский", "ок. 1111–1174", "andrey_bogolyubsky.jpg", "Владимиро-суздальский князь, перенёсший столицу княжества во Владимир.", "Андрей Юрьевич Боголюбский родился между 1120 и 1125 годами, был сыном Юрия Долгорукого от первого брака с дочерью половецкого хана. В 1155 году вопреки воле отца покинул Вышгород и уехал в Суздальскую землю, увезя с собой вышгородскую икону Богородицы, ставшую впоследствии Владимирской иконой. После смерти Юрия Долгорукого в 1157 году занял ростово-суздальский стол и перенёс центр княжества из Ростова и Суздаля во Владимир-на-Клязьме. В 1169 году организовал поход на Киев, после чего «старейшинство» владимирского князя признали другие князья. Прозвище получил по названию своей резиденции Боголюбово под Владимиром. Был убит в ночь на 29 июня 1174 года в результате заговора, главную роль в котором сыграл боярский род Кучковичей."),
            SeedPersonality(1, "Всеволод Большое Гнездо", "1154–1212", "vsevolod_bolshoe_gnezdo.jpg", "Великий князь владимирский, при котором Владимиро-Суздальская земля достигла могущества.", "Всеволод Юрьевич родился 19 октября 1154 года, был младшим сыном Юрия Долгорукого от второго брака. В 1162 году вместе с матерью и братьями был изгнан старшим братом Андреем Боголюбским и уехал в Византию, где провёл несколько лет. Вернувшись на Русь, в 1176 году после смерти брата Михаила занял владимирский престол. В 1177 году разбил войско племянника Мстислава Ростиславича и рязанского князя Глеба на реке Колокше, укрепив свою власть. Прозвище «Большое Гнездо» получил за многодетность — у него было 12 детей, восемь сыновей и четыре дочери. Умер 15 апреля 1212 года во Владимире."),
            SeedPersonality(1, "Даниил Галицкий", "1201–1264", "daniil_galitsky.jpg", "Галицко-волынский князь, объединивший юго-западные земли и принявший королевский титул.", "Даниил Романович родился в 1201 году, был сыном галицко-волынского князя Романа Мстиславича. После гибели отца в 1205 году детство и юность прошли в борьбе за отцовское наследство с боярами и соседними князьями. В 1221 году стал княжить на Волыни, а в 1238 году окончательно овладел Галичем, завершив объединение галицких и волынских земель. В 1245 году в битве под Ярославлем разгромил войска венгров и поляков, завершив многолетнюю борьбу за восстановление единства княжества. В 1253 году был коронован папой римским как первый и единственный коронованный русский король, однако решительно противостоял попыткам распространения католического влияния. Основал города Холм, Львов, Данилов, перенёс столицу княжества в Холм. Умер в 1264 году."),
            SeedPersonality(1, "Сергий Радонежский", "ок. 1314–1392", "sergiy_radonezhskiy.jpg", "Основатель Троицкого монастыря, духовный наставник Дмитрия Донского.", "Сергий Радонежский, в миру Варфоломей, родился около 1314 года в семье ростовских бояр Кирилла и Марии. После смерти родителей вместе со старшим братом Стефаном удалился в лес на холме Маковец, где построил келью и церковь во имя Святой Троицы. Около 1337 года принял монашеский постриг с именем Сергий. К нему стали приходить иноки, и между 1353 и 1356 годами он стал игуменом возникшего Троицкого монастыря. В 1380 году благословил князя Дмитрия Ивановича и русское войско на битву с Мамаем, что придало сражению духовный характер. Его ученики основали до двадцати монастырей по всей Руси, за что Сергия называют «игуменом земли Русской». Умер 25 сентября 1392 года, канонизирован не позднее 1448 года."),
            SeedPersonality(1, "Митрополит Иларион", "XI век", "ilarion_metropolitan.jpg", "Первый русский митрополит, автор «Слова о законе и благодати».", "Иларион был священником придворной церкви святых Апостолов в Берестове под Киевом и пользовался расположением князя Ярослава Мудрого. В 1051 году был поставлен митрополитом Киевским и всея Руси собором русских епископов без согласования с Константинопольским патриархатом, что стало важным шагом к независимости русской церкви. Был автором первого дошедшего до нас оригинального памятника древнерусской литературы — торжественного «Слова о законе и благодати», в котором прославлял крещение Руси и князя Владимира. Оставил митрополичью кафедру, вероятно, после смерти Ярослава Мудрого в 1054 году; дальнейшие сведения о его жизни отрывочны."),

            SeedPersonality(2, "Иван III", "1440–1505", "ivan_iii.jpg", "Великий князь, при котором завершилось объединение земель и прекратилась зависимость от Орды.", "Иван III Васильевич родился 22 января 1440 года в Москве в семье великого князя Василия II Тёмного и княгини Марии Ярославны. Его детство и юность пришлись на междоусобную войну, в ходе которой отец был ослеплён и на время лишён престола. Уже в двенадцать лет Иван был обвенчан с дочерью тверского князя Марией Борисовной и стал соправителем отца; в пятнадцать лет совершил свой первый поход против татар, а к двадцати годам возглавил войско Московского княжества. После смерти Василия II в 1462 году Иван III занял московский престол и правил до 1505 года. За годы его правления территория государства увеличилась почти втрое: к Москве были присоединены Ярославское княжество (1463), Ростовское (1474), Новгородская республика (1478), Тверское княжество (1485), Вятская земля (1489) и другие территории. В 1480 году после стояния на реке Угре ордынское владычество над русскими землями было окончательно прекращено. При Иване III был принят Судебник 1497 года — первый общерусский свод законов, начала складываться приказная система управления, сформировалась государственная символика с двуглавым орлом. В 1472 году он женился на византийской царевне Софье Палеолог, что способствовало укреплению международного престижа Москвы. Умер 27 октября 1505 года."),
            SeedPersonality(2, "Василий III", "1479–1533", "vasily_iii.jpg", "Великий князь, завершивший объединение русских земель вокруг Москвы.", "Василий III Иванович родился 25 марта 1479 года в семье Ивана III и византийской царевны Софьи Палеолог. После смерти в 1490 году наследника престола Ивана Молодого, сына Ивана III от первого брака, развернулась борьба за престолонаследие, из которой Василий вышел победителем: он был назначен сначала великим князем Новгорода и Пскова, а затем стал соправителем отца. После смерти Ивана III в 1505 году беспрепятственно вступил на престол. Продолжая политику отца, Василий III окончательно ликвидировал систему удельных княжеств: в 1510 году был присоединён Псков, в 1513 году — Волоцкий удел, в 1521 году — Рязанское княжество, в 1522 году — Новгород-Северское. В ходе русско-литовской войны 1512–1522 годов в 1514 году был взят Смоленск. Для борьбы с Казанским ханством вблизи Казани была построена крепость Васильсурск. Первый брак с Соломонией Сабуровой оказался бездетным; в 1526 году Василий женился на княжне Елене Глинской, а в 1530 году у них родился сын — будущий царь Иван IV. Умер 4 декабря 1533 года, похоронен в Архангельском соборе Московского Кремля."),
            SeedPersonality(2, "Иван IV Грозный", "1530–1584", "ivan_grozny.jpg", "Первый венчанный на царство русский царь, при котором началось расширение государства на восток.", "Иван IV Васильевич родился 25 августа 1530 года в семье великого князя Василия III и Елены Глинской. После смерти отца в 1533 году и матери в 1538 году рос в обстановке боярских усобиц, которые тяжело отразились на его характере. В 1547 году в Успенском соборе Московского Кремля он венчался на царство, приняв титул «царя Всея Руси», что знаменовало начало Московского царства. В конце 1540-х — 1550-х годах при участии Избранной рады провёл серию реформ: созвал Земский собор (1549), издал Судебник (1550), усовершенствовал приказную систему, создал постоянное стрелецкое войско, созвал Стоглавый собор (1551). В 1552 году покорил Казанское ханство, в 1556 году — Астраханское, в 1557 году — Башкирию. В 1558 году начал Ливонскую войну за выход к Балтийскому морю, завершившуюся неудачей. В 1565 году учредил опричнину, сопровождавшуюся массовыми репрессиями и политическими заговорами (1567, 1569). Покровительствовал развитию культуры, церковному строительству и книгопечатанию: в 1564 году Иван Фёдоров выпустил «Апостол». Умер 18 марта 1584 года."),
            SeedPersonality(2, "Анастасия Романовна", "ок. 1530–1560", "anastasiya_romanovna.jpg", "Первая супруга Ивана IV, представительница рода Захарьиных-Юрьевых.", "Анастасия Романовна Захарьина-Юрьева родилась около 1531/32 года (по другим данным — 1533) в семье окольничего Романа Юрьевича Захарьина-Юрьева и Ульяны Ивановны. После смерти отца в 1543 году воспитывалась матерью. По свидетельству «Летописца начала царства», была выбрана в невесты лично царём Иваном IV; венчание провёл митрополит Московский Макарий в Успенском соборе 3 февраля 1547 года. Современники отмечали её добродетель, благочестие и благотворное влияние на мужа; князь Курбский писал, что она пользовалась любовью народа. Анастасия неоднократно совершала обетные паломничества, в том числе пешком в Троице-Сергиев монастырь, сопровождала мужа в поездках по монастырям. При её светлице существовала мастерская, где вышивались церковные пелены и покровы; сохранилось более полутора десятков произведений, связанных с её именем. Умерла 7 августа 1560 года в селе Коломенском. Смерть царицы современники связывали с отравлением, и Иван Грозный обвинил в «чародействе» своих бывших советников Сильвестра и Адашева. Род Захарьиных-Юрьевых, к которому она принадлежала, впоследствии стал основой династии Романовых."),
            SeedPersonality(2, "Ермак Тимофеевич", "ок. 1532–1585", "ermak.jpg", "Казачий атаман, возглавивший поход за Урал против Сибирского ханства.", "Ермак Тимофеевич родился около 1540 года (по другим данным — около 1532); сведения о его происхождении отрывочны и противоречивы. Существуют версии, что он был родом с берегов Камы, из Тотьмы, с Северной Двины или с Дона; точно установить его происхождение не удаётся. Длительное время его отряд волжских казаков действовал против татар в Поволжье. В начале 1580-х годов Строгановы пригласили его отряд для обороны своих владений в Пермском крае от набегов татар и вогулов. В конце августа — начале сентября 1582 года отряд Ермака численностью около 540 человек (с ними также шли 300 литовцев и немцев — военнопленных, служивших у Строгановых) начал поход в Сибирь. Казаки располагали огнестрельным оружием, что давало преимущество перед татарской конницей. Отряд разгромил силы сибирского хана Кучума в нескольких сражениях, а 23 октября (2 ноября) 1582 года в решающей битве под Чувашевом в устье реки Тобол нанёс поражение войску Маметкула, племянника Кучума. В октябре 1582 года Ермак занял столицу Сибирского ханства Кашлык. Погиб в ночь с 5 на 6 августа 1585 года в бою с татарами на реке Вагай. Поход Ермака положил начало присоединению Сибири к Русскому государству."),
            SeedPersonality(2, "Борис Годунов", "ок. 1551–1605", "boris_godunov.jpg", "Русский царь, правивший накануне Смутного времени.", "Борис Фёдорович Годунов родился около 1551/1552 года в семье боярина Фёдора Годунова. Годуновы вели происхождение от костромских бояр, служивших московским князьям, но не входивших в высшую знать. Возвышение Бориса началось после вступления в опричнину и сближения с Малютой Скуратовым; около 1570 года он женился на дочери Скуратова Марии. Несколько позже его сестра Ирина вышла замуж за царевича Фёдора Ивановича, что упрочило положение Годунова при дворе и обеспечило получение боярского чина в 1580 году. После смерти Ивана Грозного в 1584 году и вступления на престол Фёдора Иоанновича, неспособного самостоятельно управлять страной, Борис Годунов стал фактически единоличным правителем государства. Его правительство добилось учреждения патриаршества в 1589 году (первым патриархом стал митрополит Иов), провело перепись земель, издало указ об «урочных летах» (1597), ликвидировало «белые слободы» в городах, поощряло колонизацию Сибири и южных районов. Во внешней политике проявил себя как талантливый дипломат. После смерти царя Фёдора в 1598 году Земский собор избрал Бориса Годунова на царство. В его правление произошли трагические события: в 1591 году в Угличе погиб царевич Дмитрий, в 1601–1603 годах страну поразил Великий голод. В 1604 году началось вторжение Лжедмитрия I. Умер 13 апреля 1605 года."),
            SeedPersonality(2, "Минин Кузьма", "ок. 1570–1616", "minin.jpg", "Земский староста, один из организаторов Второго народного ополчения.", "Кузьма Минин (Кузьма Минич, фамилия точно не установлена; известна также как Сухорук) родился, по разным данным, в 1560-х или 1570-х годах. Происходил из семьи, принадлежавшей к средним слоям посада Нижнего Новгорода; сам был посадским человеком из «молодших», то есть небогатых. В августе — октябре 1611 года, во время польско-литовской интервенции, призывал к борьбе с интервентами. Предположительно 1 сентября 1611 года был избран земским старостой Нижнего Новгорода и обратился к горожанам с призывом «помочь Московскому государству», ссылаясь на слова увиденного во сне преподобного Сергия Радонежского. Его инициатива была поддержана посадскими людьми и духовенством; были собраны средства на формирование Второго ополчения, воеводой которого стал князь Дмитрий Пожарский, а Минин отвечал за казну. По пути к Москве он организовывал сбор чрезвычайного налога для выплаты жалованья ратным людям. В августе 1612 года участвовал в освобождении Москвы; 24 августа (3 сентября) командовал отрядом, удар которого во фланг войска гетмана Ходкевича во многом решил исход сражения. 12 июля 1613 года, на следующий день после венчания на царство Михаила Фёдоровича, был пожалован в думные дворяне — единственный в истории случай пожалования столь высокого чина человеку недворянского происхождения. Умер в 1616 году; гробница с 1962 года находится в Михаило-Архангельском соборе Нижегородского кремля."),
            SeedPersonality(2, "Дмитрий Пожарский", "1578–1642", "pozharsky.jpg", "Князь, возглавивший Второе народное ополчение вместе с Кузьмой Мининым.", "Дмитрий Михайлович Пожарский родился 1 ноября 1578 года в семье князя Михаила Фёдоровича Пожарского. Службу начал в чине «стряпчего с платьем»: в 1598 году подписал Утверждённую грамоту об избрании на царство Бориса Годунова. Участвовал в подавлении восстания Болотникова (1606–1607), разбил польско-литовский отряд в селе Высокое (1608/09), был воеводой в Зарайске (1610). Весной 1611 года участвовал в восстании москвичей против польско-литовского гарнизона и был тяжело ранен. Стал одним из организаторов и руководителей Второго ополчения 1611–1612 годов, его первым воеводой; рассылал грамоты в города с призывом присоединиться к ополчению, отправлял отряды для защиты и освобождения Ярославля, Суздаля, Углича и других городов. Весной 1612 года вошёл в состав Земского правительства. В августе 1612 года руководил ополчением при освобождении Москвы от польско-литовских войск. После избрания Михаила Романова на царство получил боярский чин и участвовал в государственном управлении. Умер 20 апреля 1642 года."),
            SeedPersonality(2, "Михаил Фёдорович Романов", "1596–1645", "mikhail_romanov.jpg", "Первый русский царь из династии Романовых, избранный Земским собором в 1613 году.", "Михаил Фёдорович Романов родился 12 (22) июля 1596 года в семье московских бояр Романовых. Его отец, Фёдор Никитич, был двоюродным братом последнего царя из династии Рюриковичей — Фёдора Ивановича; мать, Ксения Ивановна Шестова, происходила из костромских дворян. В 1601 году Романовы пали в немилость, и по приказу Бориса Годунова родителей Михаила насильственно постригли в монахи. Во время польской оккупации Москвы Михаил находился в плену в Кремле, откуда был освобождён в 1612 году Вторым ополчением. В январе 1613 года в Москве открылся Земский собор для избрания нового царя; по инициативе и под давлением «вольного казачества» одобрение получила кандидатура Михаила Фёдоровича. 21 февраля (3 марта) 1613 года произошло официальное избрание, а 11 (21) июля 1613 года он венчался на царство в Успенском соборе. В первые годы правления большинство государственных и внешнеполитических вопросов решал совместно с отцом, который в 1619 году стал патриархом Филаретом и фактически управлял государством до своей смерти в 1633 году. Главной задачей царствования было преодоление последствий Смуты: в 1617 году был заключён Столбовский мир со Швецией, в 1618 году — Деулинское перемирие с Речью Посполитой, в 1634 году — Поляновский мир. В годы его правления выросла система воеводского управления, получила развитие приказная система, началось составление новых писцовых книг, были введены полки иноземного строя. Умер 13 (23) июля 1645 года, похоронен в Архангельском соборе Московского Кремля."),
            SeedPersonality(2, "Софья Алексеевна", "1657–1704", "sofya_alekseevna.jpg", "Правительница-регент при малолетних Иване V и Петре I.", "Софья Алексеевна родилась в 1657 году в семье царя Алексея Михайловича и Марии Ильиничны Милославской, была шестым ребёнком из шестнадцати детей государя. Вопреки традициям воспитания царевен, получила образование под руководством известного учёного и поэта Симеона Полоцкого: освоила чтение и письмо, изучала греческий и латинский языки, историю и богословскую литературу. После смерти царя Фёдора Алексеевича в 1682 году в ходе борьбы между Милославскими и Нарышкиными и стрелецкого бунта добилась провозглашения Ивана V и Петра I соправителями при своём регентстве. В годы регентства (1682–1689) фактически управляла государством при участии князя Василия Голицына. В 1686 году заключила Вечный мир с Речью Посполитой, в 1687 и 1689 годах организовала Крымские походы, завершившиеся неудачей. В 1689 году была отстранена от власти Петром I и заключена в Новодевичий монастырь. Умерла 3 июля 1704 года."),

